/* ROPO Fleet local demonstration. No vehicle or production service is connected. */
window.Fleet={pages:{},route:'overview',storageKey:'ropo-fleet-prototype-v1'};
(()=>{
const F=window.Fleet;
F.h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',vehicles:'M5 6h14l2 7v7h-3v-3H6v3H3v-7zM3 12h18M7 15h1m8 0h1',plans:'M5 3v5l7 5v8M19 3v5l-7 5M3 5h4m10 0h4',remote:'M4 14v-3a8 8 0 0 1 16 0v3M4 12H2v7h4v-7zm14 0h4v7h-4zm0 7v3h-6',logs:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h5',settings:'M4 5h16M4 12h16M4 19h16M8 2v6m8 1v6M10 16v6',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zM10 21h4',arrow:'M4 12h16m-6-6 6 6-6 6',pin:'M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 1 1 14 0ZM10 9h4',check:'m5 12 4 4L19 6',flow:'M4 4h6v6H4zm10 10h6v6h-6zM7 10v7h7',battery:'M3 7h17v10H3zM22 10v4M6 10v4m3-4v4m3-4v4',play:'m8 4 12 8-12 8z',back:'M20 12H4l6-6m-6 6 6 6',close:'m6 6 12 12M18 6 6 18',clock:'M12 7v5l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
F.icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.overview}"/></svg>`;
F.status={running:['运行中','blue'],standby:['就绪待命','green'],waiting:['等待发车','amber'],charging:['补能中','purple'],maintenance:['维修中','muted'],offline:['离线','red'],completed:['已完成','green'],cancelled:['已取消','muted']};
F.badge=s=>`<span class="badge ${F.status[s]?.[1]||'muted'}">${F.status[s]?.[0]||F.h(s)}</span>`;
F.seed=()=>{
 const vehicles=Array.from({length:50},(_,j)=>{const i=j+1,id='RT-'+String(i).padStart(3,'0');let status=i<=28?'running':i<=38?'standby':i<=44?'charging':i<=48?'maintenance':'offline';return {id,plate:'沪AD'+String(2100+i*37),soc:35+(i*7)%64,status,speed:status==='running'?28+(i*3)%18:0,range:Math.round((35+(i*7)%64)*2.8),location:'张江 · 科苑路'};});
 const overrides={'RT-021':{status:'waiting',soc:32,plate:'沪AD02198',range:86,speed:0},'RT-034':{status:'standby',soc:56,plate:'沪AD03461',range:160},'RT-008':{status:'running',soc:68,plate:'沪AD00812',range:194},'RT-041':{status:'charging',soc:27,plate:'沪AD04185',range:78},'RT-046':{status:'offline',soc:74,plate:'沪AD04603',speed:0},'RT-019':{status:'maintenance',soc:50,speed:0},'RT-012':{status:'standby',soc:81,speed:0},'RT-029':{status:'running',speed:36},'RT-030':{status:'running',speed:32},'RT-031':{status:'running',speed:38},'RT-050':{status:'standby',speed:0}};
 vehicles.forEach(v=>Object.assign(v,overrides[v.id]||{}));
 return {vehicles,selectedId:'RT-021',selectedPlan:'S-1023-028',plans:[{id:'S-1023-028',vehicleId:'RT-021',type:'回场补能',origin:'科苑路 03 机位',destination:'张江运营中心 4 号超充桩',start:'10:18',end:'11:00',status:'waiting'},{id:'T-1023-094',vehicleId:'RT-008',type:'接送任务',origin:'金科路地铁站',destination:'浦东软件园',start:'09:40',end:'11:35',status:'running'},{id:'D-1023-012',vehicleId:'RT-034',type:'车辆调位',origin:'张江北区',destination:'嘉定热点区',start:'10:00',end:'11:30',status:'waiting'},{id:'S-1023-026',vehicleId:'RT-041',type:'回场补能',origin:'科苑路',destination:'张江运营基地充电泊位',start:'09:50',end:'10:50',status:'running'},{id:'M-1023-005',vehicleId:'RT-046',type:'停运检修',origin:'维修厂区西侧',destination:'维修厂区',start:'08:30',end:'16:00',status:'waiting'}],logs:[{time:'10:19:42',text:'RT-021 路线规划已载入，等待运营员确认发车',kind:'system'},{time:'10:19:12',text:'RT-008 前方施工延误 +7 分钟，生成改道建议',kind:'system'},{time:'10:18:05',text:'车队状态已同步（原稿演示场景）',kind:'system'}],flow:null,settings:{sound:true,compact:false},draft:null};
};
try{const raw=JSON.parse(localStorage.getItem(F.storageKey));F.state=raw?.vehicles?.length&&raw?.plans&&raw?.logs?raw:F.seed();}catch{F.state=F.seed();}
F.save=()=>{try{localStorage.setItem(F.storageKey,JSON.stringify(F.state));}catch{F.toast('浏览器未允许本地存储，本次操作仅在当前窗口保留','warning');}};
F.log=(text,kind='action')=>{F.state.logs.unshift({time:new Date().toLocaleTimeString('zh-CN',{hour12:false}),text,kind});F.save();};
F.vehicle=()=>F.state.vehicles.find(v=>v.id===F.state.selectedId)||F.state.vehicles[0];
F.plan=()=>F.state.plans.find(p=>p.id===F.state.selectedPlan)||F.state.plans[0];
F.toast=(message,type='success')=>{const t=document.querySelector('#toast');t.textContent=message;t.className='show '+type;clearTimeout(F.toastTimer);F.toastTimer=setTimeout(()=>t.className='',4000);};
F.modal=(title,body,onSubmit)=>{const d=document.querySelector('#modal');document.querySelector('#modal-title').textContent=title;document.querySelector('#modal-body').innerHTML=body;document.querySelector('#modal-form').onsubmit=e=>{e.preventDefault();const result=onSubmit?.(new FormData(e.currentTarget),d);if(result!==false)d.close();};if(!d.open)d.showModal();};
F.confirm=(title,text,action,label='确认')=>F.modal(title,`<p class="dialog-description">${F.h(text)}</p><div class="dialog-actions"><button type="button" class="btn subtle" data-action="close-modal">取消</button><button class="btn primary" type="submit">${F.h(label)}</button></div>`,action);
F.go=route=>{if(location.hash==='#'+route)F.render();else location.hash=route;};
F.selectVehicle=id=>{F.state.selectedId=id;F.save();F.go('detail');};
const titles={overview:'运营总览',vehicles:'车辆管理',detail:'车辆详情',plans:'任务与调度',create:'创建运行计划',remote:'远程运营',automation:'自动化流程',logs:'记录与交班',settings:'系统设置'};
F.render=()=>{
 F.route=location.hash.slice(1)||'overview';if(!F.pages[F.route])F.route='overview';
 const group=['detail'].includes(F.route)?'vehicles':['create','automation'].includes(F.route)?'plans':F.route;
 document.title=`${titles[F.route]} · ROPO Fleet`;
 document.querySelector('#sidebar').innerHTML=`<a class="brand" href="#overview"><span class="brand-mark">Λ</span><span><small>ROPO FLEET</small> ROPO Fleet</span></a><nav aria-label="主导航">${[['overview','运营总览'],['vehicles','车辆管理'],['plans','任务与调度'],['remote','远程运营'],['logs','记录与交班'],['settings','系统设置']].map(([k,v])=>`<a href="#${k}" class="nav-link ${group===k?'active':''}" ${group===k?'aria-current="page"':''}>${F.icon(k)}<span>${v}</span></a>${k==='plans'&&group==='plans'?`<a class="subnav ${F.route==='automation'?'selected':''}" href="#automation">自动化流程 <span>↗</span></a>`:''}`).join('')}</nav><footer><div>班次 <span>早班 · 08:00–16:00</span></div><div>环境 <span class="green">● 交互原型 / 模拟数据</span></div><div>版本 <span>v2.4.12-rc</span></div></footer>`;
 document.querySelector('#topbar').innerHTML=`<div class="location">${F.icon('pin')} 上海 · 张江 <span class="badge green">正常运营</span></div><form id="global-search" role="search">${F.icon('search')}<input aria-label="全局搜索车辆编号或计划编号" placeholder="全局搜索车辆编号（如 RT-021）、计划编号…" autocomplete="off"></form><span class="demo-pill">交互演示 · 本地数据</span><button class="icon-btn notifications" aria-label="查看待处理提醒" data-action="notifications">${F.icon('bell')}<b>3</b></button><button class="icon-btn" aria-label="使用说明" data-action="help">?</button><button class="user-chip" data-action="profile"><span>员</span> 员工ABDD</button>`;
 const page=document.querySelector('#page');if(F.cleanup){F.cleanup();F.cleanup=null;}page.innerHTML=F.pages[F.route].render();F.pages[F.route].mount?.(page);document.querySelector('#announcer').textContent=titles[F.route];
 document.querySelector('#global-search').onsubmit=e=>{e.preventDefault();const q=e.currentTarget.querySelector('input').value.trim().toUpperCase();if(!q)return;const v=F.state.vehicles.find(v=>v.id===q||v.plate.toUpperCase()===q);const p=F.state.plans.find(p=>p.id===q);if(v)F.selectVehicle(v.id);else if(p){F.state.selectedPlan=p.id;F.state.selectedId=p.vehicleId;F.save();F.go('plans');}else F.toast('未找到该车辆或计划，请输入完整编号，如 RT-021','warning');};
};
document.addEventListener('click',e=>{if(e.target.closest('.skip-link')){e.preventDefault();document.querySelector('#page').focus();return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 if(a==='close-modal'){document.querySelector('#modal').close();return;}
 if(a==='go'){F.go(b.dataset.route);return;}if(a==='vehicle'){F.selectVehicle(b.dataset.id);return;}
 if(a==='help'){F.modal('原型使用说明',`<div class="help-content"><p>这是根据 7 张 Figma SVG 制作的交互演示。所有操作只影响本浏览器的模拟数据。</p><ol><li>车辆管理：搜索、筛选，点击车辆查看详情。</li><li>任务与调度：创建计划，调整时段或换车。</li><li>远程运营：确认条件后模拟发车、停车和广播。</li><li>自动化流程：拖动节点、配置规则、模拟执行。</li></ol><p>摄像头与地图为原稿静态素材。发车与急停不会向真实车辆发送指令。</p><p>系统设置中可以恢复初始演示数据。</p></div><div class="dialog-actions"><button class="btn primary">开始体验</button></div>`);return;}
 if(a==='notifications'){F.modal('待处理事项',`<div class="notice-list"><button type="button" data-action="notification-vehicle" data-id="RT-021">${F.badge('waiting')} RT-021 · 等待发车确认 →</button><button type="button" data-action="notification-vehicle" data-id="RT-008">${F.badge('running')} RT-008 · 前方施工延误 +7 分钟 →</button><button type="button" data-action="notification-vehicle" data-id="RT-046">${F.badge('offline')} RT-046 · 通信中断 →</button></div>`);return;}
 if(a==='notification-vehicle'){document.querySelector('#modal').close();F.selectVehicle(b.dataset.id);return;}
 if(a==='profile'){F.modal('当前操作员',`<div class="profile-card"><span class="avatar">员</span><h3>员工ABDD</h3><p>张江运营中心 · 早班运营员</p><p class="muted">演示身份，无需登录。</p></div><div class="dialog-actions"><button class="btn primary">关闭</button></div>`);return;}
 F.pages[F.route]?.action?.(a,b,e);
});
document.querySelector('#modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});
addEventListener('hashchange',()=>{F.render();scrollTo(0,0);});addEventListener('DOMContentLoaded',F.render);
})();
